 12	import { runCommand, type PodmanExecutor } from '@thyrox/podman-execution/podmanExecutor.ts'
 13	import { workerContainerName, type WorkerContainerSpec } from '@thyrox/podman-execution/workerContainerLifecycle.ts'
 14	import { workerResourceLimitArgv, type WorkerResourceProfile } from '@thyrox/podman-execution/workerResourceProfile.ts'
 15	
 16	/** Dónde ve el contenedor el scratch del anfitrión. */
 17	export const LAB_SCRATCH_MOUNT = '/scratch'
