 63	    private readonly owner: LabOwner,
 64	  ) {}
 65	
 66	  async run(step: LabStep): Promise<LabStepResult> {
 67	    const containerName = workerContainerName(step.workerId)
 68	    const peak = new PeakTracker()
 69	    const sampler = setInterval(() => { void this.probe(containerName).then(value => peak.observe(value)) }, MEMORY_SAMPLE_INTERVAL_MS)
 70	    try {
 71	      const output = await runJobWithOutput(this.podman, this.specOf(step))
 72	      return { ...output, ...peak.asResult() }
 73	    } finally {
 74	      clearInterval(sampler)
 75	    }
 76	  }
 77	
 78	  private specOf(step: LabStep): WorkerContainerSpec {
 79	    return {
 80	      workerId: step.workerId,
 81	      image: this.imageId,
 82	      owner: { kind: 'lab', id: this.owner.id, pid: this.owner.pid },
 83	      resourceArgv: workerResourceLimitArgv(this.profile()),
 84	      command: step.command,
 85	    }
 86	  }
 87	
 88	  private profile(): WorkerResourceProfile {
 89	    return {
 90	      cpus: this.limits.cpus,
 91	      memoryMib: Math.floor(this.limits.memoryBytes / BYTES_PER_MIB),
 92	      pidsLimit: LAB_PIDS_LIMIT,
 93	      network: 'none',
 94	      readOnlyRootfs: false,
 95	      mounts: [{ source: this.scratchDir, destination: LAB_SCRATCH_MOUNT, mode: 'rw' }],
 96	    }
 97	  }
 98	}
 99	
100	class PeakTracker {
101	  private peak: number | undefined
102	
103	  observe(value: number | undefined): void {
104	    if (value !== undefined && (this.peak === undefined || value > this.peak)) this.peak = value
105	  }
106	
107	  asResult(): { peakMemoryBytes?: number } {
108	    return this.peak === undefined ? {} : { peakMemoryBytes: this.peak }
109	  }
110	}
