112	/** `container_measure read <name>` publica `measured <pico> <uso> <pids>`; otro estado no es una medida. */
113	export function parseContainerMeasure(stdout: string): number | undefined {
114	  const [state, peak] = stdout.trim().split(/\s+/)
115	  if (state !== MEASURED_STATE || peak === undefined) return undefined
116	  const value = Number(peak)
117	  return Number.isFinite(value) ? value : undefined
118	}
119	
120	export function containerMeasureProbe(containerMeasureBin: string): ContainerMemoryProbe {
121	  return async name => parseContainerMeasure((await runCommand(containerMeasureBin, ['read', name])).stdout)
122	}
